"""One-off seed of publishing/pins/*.json and publishing/content-plan.json (26 Nov 2026).
After this, edit the JSON files directly; re-running overwrites them."""
import json, os, datetime as dt
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
P = os.path.join(ROOT, "publishing")
AI = "Made from AI-generated inspiration images (not product photos). Tick Pinterest's AI label when uploading."
NOAI = "Original text graphic; no AI imagery."
B = {"press": "Press-On Nails", "xmas": "Christmas Nails", "short": "Short Nail Designs", "almond": "Almond Nail Designs",
     "french": "French Tip Nails", "chrome": "Chrome & Cat Eye Nails", "art": "Nail Art Ideas & Nail Inspo",
     "decor": "Christmas Apartment Decor", "nye": "New Year's Nails"}

def dates(start, n, gap):
    d = dt.date.fromisoformat(start)
    return [(d + dt.timedelta(days=i * gap)).isoformat() for i in range(n)]

def pkg(slug, url, ptype, start, gap, pins):
    ds = dates(start, len(pins), gap)
    out = []
    for i, (p, d) in enumerate(zip(pins, ds), 1):
        p = dict(p)
        p["id"] = f"{slug}--{p['file'][:-4]}"
        p["destination"] = url + (p.pop("anchor", "") and "#" + p.get("_a", "")) if False else url + p.pop("hash", "")
        p["aiDisclosure"] = AI if p.get("images") else NOAI
        p["publishDate"] = d
        p["status"] = "draft"
        out.append(p)
    json.dump({"article": slug, "articleUrl": url, "packageType": ptype,
               "_README": "One Pin package per article. Images are generated by `npm run pins` into pinterest-pins/<article>/. Status: draft -> ready (reviewed by hand) -> published (posted by hand, add pinUrl). Never auto-post.",
               "pins": out}, open(os.path.join(P, "pins", slug + ".json"), "w"), indent=2, ensure_ascii=False)
    return out

def pin(file, template, images, headline, title, description, keywords, board, alt, hash="", **kw):
    return dict(file=file, direction=kw.pop("direction"), template=template, images=images, headline=headline, title=title,
                description=description, keywords=keywords, board=board, altText=alt, hash=hash, **kw)

